    protected string $componentClass = Pagination::class;

    protected array $defaultProperties = [
        'perPageValues'    => [10, 20, 50, 100],
        'simple'           => false,
        'compact'          => false,
        'advanced'         => false,
        'minimal'          => false,
        'hidePerPage'      => false,
        'hidePageInfo'     => false,
        'showFirstLast'    => true,
        'showJumpTo'       => false,
        'onEachSide'       => 1,
        'size'             => 'default',
        'showPageInfo'     => true,
