    public function test_pagination_string_properties(): void
    {
        $stringProperties = ['id', 'size', 'pageInfoTemplate'];
        $testValues       = ComponentDataFactory::sampleTexts();

        foreach ($stringProperties as $property) {
            foreach ($testValues as $value) {
                if (empty($value)) {
                    continue;
                } // Skip empty values for some properties

                $component = $this->createComponent([$property => $value]);
                $this->assertEquals($value, $component->$property);
            }
        }
    }

    public function test_pagination_boolean_properties(): void
    {
        $booleanProperties = ['simple', 'compact', 'advanced', 'minimal', 'hidePerPage', 'hidePageInfo', 'showFirstLast', 'showJumpTo', 'showPageInfo'];

        foreach ($booleanProperties as $property) {
            $component = $this->createComponent([$property => true]);
            $this->assertTrue($component->$property);

            $component = $this->createComponent([$property => false]);
            $this->assertFalse($component->$property);
        }
    }

    public function test_pagination_array_properties(): void
    {
        $arrayProperties = ['perPageValues'];
        $testArrays      = ComponentDataFactory::arrayData();

        foreach ($arrayProperties as $property) {
            foreach ($testArrays as $array) {
                $component = $this->createComponent([$property => $array]);
                $this->assertEquals($array, $component->$property);
            }
        }
    }

    public function test_pagination_model_name_method(): void
    {
        $component = $this->createComponent();

        if (method_exists($component, 'modelName')) {
            try {
                $result = $component->modelName();
                // Add specific assertions based on expected return type
                $this->assertNotNull($result);
            } catch (Error $e) {
                if (str_contains($e->getMessage(), 'Call to a member function') &&
                    str_contains($e->getMessage(), 'on null')) {
                    $this->markTestSkipped('Method requires attributes or context');
                }
                throw $e;
            }
        }
    }

